import fs from 'fs/promises';
import os from 'os';
import path from 'path';
import { parseArgs, run } from '../cli';

describe('parseArgs', () => {
  it('defaults content and output directories', () => {
    const result = parseArgs(['node', 'ssg', 'build']);
    expect(result.command).toBe('build');
    expect(result.options.contentDir).toBe('./content');
    expect(result.options.outputDir).toBe('./dist');
    expect(result.options.templateDir).toBe('./templates');
  });

  it('reads --content and --output options', () => {
    const result = parseArgs([
      'node',
      'ssg',
      'build',
      '--content',
      './pages',
      '--output',
      './site',
    ]);
    expect(result.options.contentDir).toBe('./pages');
    expect(result.options.outputDir).toBe('./site');
  });

  it('supports short flags', () => {
    const result = parseArgs(['node', 'ssg', 'build', '-c', './pages', '-o', './site']);
    expect(result.options.contentDir).toBe('./pages');
    expect(result.options.outputDir).toBe('./site');
  });

  it('reads --templates option', () => {
    const result = parseArgs([
      'node',
      'ssg',
      'build',
      '--templates',
      './theme',
    ]);
    expect(result.options.templateDir).toBe('./theme');
  });

  it('parses the serve command', () => {
    const result = parseArgs(['node', 'ssg', 'serve']);
    expect(result.command).toBe('serve');
  });

  it('reads --port option', () => {
    const result = parseArgs(['node', 'ssg', 'serve', '--port', '8080']);
    expect(result.options.port).toBe(8080);
  });

  it('supports the short --port flag', () => {
    const result = parseArgs(['node', 'ssg', 'serve', '-p', '4000']);
    expect(result.options.port).toBe(4000);
  });

  it('throws on an invalid port', () => {
    expect(() => parseArgs(['node', 'ssg', 'serve', '--port', 'notaport'])).toThrow(
      'Invalid port'
    );
    expect(() => parseArgs(['node', 'ssg', 'serve', '--port', '99999'])).toThrow(
      'Invalid port'
    );
  });

  it('throws on an unknown option', () => {
    expect(() => parseArgs(['node', 'ssg', 'build', '--bogus'])).toThrow(
      'Unknown option or command'
    );
  });
});

describe('run', () => {
  it('builds the site end to end', async () => {
    const root = await fs.mkdtemp(path.join(os.tmpdir(), 'ssg-cli-'));
    const contentDir = path.join(root, 'content');
    const outputDir = path.join(root, 'out');

    await fs.mkdir(contentDir, { recursive: true });
    await fs.writeFile(
      path.join(contentDir, 'about.md'),
      '---\ntitle: About Us\ntags: [meta]\n---\n# About\nWe make static sites.'
    );

    await run(['node', 'ssg', 'build', '--content', contentDir, '--output', outputDir]);

    const index = await fs.readFile(path.join(outputDir, 'index.html'), 'utf-8');
    expect(index).toContain('About Us');

    const about = await fs.readFile(path.join(outputDir, 'about.html'), 'utf-8');
    expect(about).toContain('We make static sites.');
  });

  it('builds with a custom templates directory via the CLI', async () => {
    const root = await fs.mkdtemp(path.join(os.tmpdir(), 'ssg-cli-tpl-'));
    const contentDir = path.join(root, 'content');
    const outputDir = path.join(root, 'out');
    const templateDir = path.join(root, 'templates');

    await fs.mkdir(contentDir, { recursive: true });
    await fs.writeFile(
      path.join(contentDir, 'home.md'),
      '---\ntitle: Home\n---\n# Home\nWelcome home.'
    );
    await fs.mkdir(path.join(templateDir, 'partials'), { recursive: true });
    await fs.mkdir(path.join(templateDir, 'layouts'), { recursive: true });
    await fs.writeFile(
      path.join(templateDir, 'default.hbs'),
      '<article>{{{body}}}</article>'
    );
    await fs.writeFile(
      path.join(templateDir, 'layouts', 'default.hbs'),
      '<html><body>{{> banner}}{{{body}}}</body></html>'
    );
    await fs.writeFile(
      path.join(templateDir, 'partials', 'banner.hbs'),
      '<p class="banner">Banner</p>'
    );

    await run([
      'node',
      'ssg',
      'build',
      '--content',
      contentDir,
      '--output',
      outputDir,
      '--templates',
      templateDir,
    ]);

    const home = await fs.readFile(path.join(outputDir, 'home.html'), 'utf-8');
    expect(home).toContain('<p class="banner">Banner</p>');
    expect(home).toContain('<article>');
    expect(home).toContain('Welcome home.');
  });
});

